solutionCode:
class GamePiece(val type: String = "cone", val points: Int = 3)

fun main() {
    val piece1 = GamePiece()
    val piece2 = GamePiece("cube", 5)
    println("${piece1.type}: ${piece1.points} points")
    println("${piece2.type}: ${piece2.points} points")
}
